/* Supplemental original educational practice; adapted to Wits example format, not official questions. Verify drug choices with local protocol: https://www.health.gov.za/nhi-edp-stgs-eml/ */
window.MED_P2_EXPANSION_ROWS=(window.MED_P2_EXPANSION_ROWS||[]).concat([{"name":"Pancreatitis","scenario":"A patient presents with severe epigastric pain radiating to the back and vomiting after a heavy meal. Lipase 900 U/L (ULN 60); ultrasound shows gallstones.","lines":[["M","What initiates pancreatic acinar injury?","Premature trypsin activation~Intrapancreatic activation of digestive enzymes causes autodigestion.","Reduced gastric pepsin activity~Does not activate pancreatic enzymes.","Increased intestinal lactase~Not implicated in acinar injury.","Reduced biliary bilirubin secretion~Does not directly initiate enzyme activation."],["D","Calcium falls, and CT shows peripancreatic fat inflammation. What causes the calcium fall?","Fat saponification~Lipase releases fatty acids that bind calcium to form soaps.","Increased PTH secretion~Would generally increase serum calcium.","Increased intestinal calcium uptake~Would oppose hypocalcaemia.","Reduced calcitonin secretion~Would tend to increase calcium."],["M","Which treatment is appropriate for uncomplicated sterile pancreatitis?","Supportive fluids and analgesia~Assess perfusion and provide early enteral nutrition as tolerated.","Routine prophylactic antibiotics~Not recommended for sterile pancreatitis.","Immediate pancreatic resection~Not routine initial management.","High-dose corticosteroids~Not routine for gallstone pancreatitis."],["V","What type of necrosis occurs in peripancreatic adipose tissue?","Fat necrosis;Enzymatic fat necrosis","Lipase releases fatty acids that undergo saponification."],["V","Which enzyme is more specific for pancreatic injury than amylase?","Lipase;Serum lipase","Usually remains elevated longer."],["M","Which finding suggests severe systemic disease requiring urgent escalation?","Persistent hypotension~May reflect hypovolaemia, systemic inflammation or organ failure.","Mild isolated nausea~Common but less concerning than shock.","Normal urine output~Reassuring for perfusion.","Improving oral intake~Suggests recovery."],["M","A patient with recurrent alcohol-related pancreatitis wants help stopping drinking. What is appropriate?","Arrange supportive alcohol treatment~Assess dependence and withdrawal risk; offer counselling and referral.","Demand immediate unsupervised withdrawal~May be unsafe in dependence.","Withhold care until abstinent~Violates equitable access.","Ignore alcohol history~Misses a modifiable risk factor."]]},{"name":"Peptic Ulcer Disease","scenario":"A man with epigastric discomfort has taken diclofenac daily. Endoscopy identifies a duodenal ulcer. A test for H. pylori is also positive.","lines":[["M","How does diclofenac damage the gastric mucosal barrier?","Reduced prostaglandin synthesis~COX inhibition reduces mucus, bicarbonate and mucosal blood flow.","Increased mucosal bicarbonate~Would improve mucosal defence.","Increased epithelial restitution~Would promote healing.","Reduced gastric acid secretion~Does not explain NSAID ulcer formation."],["M","Which drug class blocks the final step of acid secretion?","Proton pump inhibitor~Irreversibly inhibits active parietal cell proton pumps.","H2 antagonist~Blocks a stimulatory receptor rather than the final pump.","Antacid~Neutralises existing luminal acid.","Mucosal coating agent~Provides protection but does not inhibit the pump."],["D","An H. pylori stool antigen test is negative while taking a PPI. What is the best interpretation?","Possible false negative~PPIs can suppress bacterial detection; follow appropriate testing protocol.","Eradication proven~Testing conditions may invalidate the result.","Antibiotic resistance confirmed~Antigen testing does not assess resistance.","Active infection definitively excluded~Cannot confidently exclude infection under these conditions."],["M","Sudden generalized pain and board-like rigidity occur. What is most likely?","Perforated ulcer~Leakage into peritoneum causes peritonitis; urgent surgical assessment.","Uncomplicated dyspepsia~Does not explain rigidity.","Gastric reflux alone~Does not cause peritonitis.","Functional abdominal pain~Not consistent with acute peritoneal signs."],["V","Which enzyme helps H. pylori survive acid?","Urease","Hydrolyses urea to ammonia and carbon dioxide."],["V","Which bacterial virulence protein is associated with oncogenic signalling in some H. pylori strains?","CagA","Can alter epithelial signalling and promote inflammation."],["M","Which behaviour helps reduce NSAID-associated ulcer recurrence?","Avoid unnecessary NSAIDs~Review analgesic alternatives and indicated gastroprotection.","Take two NSAIDs together~Increases risk without reliable extra benefit.","Use NSAIDs on an empty stomach~Does not prevent ulceration.","Ignore melena if pain improves~Bleeding may occur without pain."]]},{"name":"Severe Acute Malnutrition","scenario":"An 18-month-old has bilateral pitting pedal oedema, sparse discoloured hair and poor appetite. MUAC 110 mm.","lines":[["M","Which mechanism contributes to oedema in oedematous malnutrition?","Reduced oncotic pressure~Hypoalbuminaemia contributes alongside altered fluid regulation and other mechanisms.","Increased plasma oncotic pressure~Would oppose interstitial fluid accumulation.","Isolated excess erythropoietin~Does not explain oedema.","Primary venous thrombosis~Would not usually cause symmetrical nutritional oedema."],["D","Glucose 2.5 mmol/L and temperature 35.3°C. Which immediate risks are present?","Hypoglycaemia and hypothermia~Both are dangerous in severe malnutrition and require urgent treatment.","Hyperglycaemia and fever~The measured values are low.","Isolated iron deficiency~Does not account for immediate findings.","Normal metabolic adaptation~These abnormalities are clinically dangerous."],["M","Which feed is appropriate during initial stabilization of complicated SAM?","F-75~Designed for cautious metabolic stabilization before catch-up feeding.","F-100 immediately~Used during rehabilitation after stabilization.","High-protein adult supplement~Not appropriate initial paediatric stabilization feed.","Unrestricted high-energy feeds~Risk metabolic decompensation."],["V","Which bedside tape measurement screens nutritional status in children 6–59 months?","MUAC;Mid upper arm circumference","MUAC below 115 mm indicates severe wasting."],["V","Which electrolyte is especially important to monitor during refeeding?","Phosphate;Serum phosphate","Insulin-driven intracellular shifts may cause severe hypophosphataemia."],["M","Why may serious infection be present without fever?","Impaired inflammatory response~Malnutrition blunts immune responses and fever.","Increased adaptive immunity~Malnutrition impairs rather than enhances defence.","Increased thermogenesis~Hypothermia is a concern.","Complete bacterial immunity~Not protective."],["M","A caregiver reports no money for food. What should the team do?","Connect family to social and nutrition services~Addresses food insecurity and improves continuity.","Give a lecture about responsibility~Does not address material barriers.","Discharge without follow-up~Risks relapse.","Withhold support until payment~Undermines equitable care."]]},{"name":"Shigellosis","scenario":"A preschool child has frequent small bloody stools, fever, tenesmus and cramping. Other children in the household have diarrhoea.","lines":[["M","Which mechanism causes dysentery?","Colonic epithelial invasion~Shigella invades mucosa and provokes intense neutrophilic inflammation.","Small-bowel noninvasive adherence alone~More typical of some watery diarrhoeal pathogens.","Preformed toxin in food alone~Usually causes rapid vomiting rather than invasive dysentery.","Loss of pancreatic enzymes~Causes malabsorptive stools."],["D","Platelets fall, creatinine rises and schistocytes appear. Which complication fits?","Haemolytic uraemic syndrome~Microangiopathic haemolysis, thrombocytopenia and AKI form the triad.","Isolated immune thrombocytopenia~Does not explain schistocytes and AKI.","Aplastic anaemia~Would reduce marrow production rather than cause fragmentation.","Iron deficiency anaemia~Does not explain acute thrombocytopenia and AKI."],["M","Which action is safest in febrile dysentery?","Rehydrate and assess antibiotic indication~Suspected Shigella dysentery warrants locally guided therapy and assessment; consider alternatives such as STEC.","Give loperamide alone~Antimotility agents are unsafe in suspected invasive diarrhoea.","Give steroids empirically~May worsen untreated infection.","Withhold oral fluids~Increases dehydration risk."],["V","Which ribosomal subunit is inactivated by Shiga toxin?","60S;60S ribosomal subunit","Depurinates 28S rRNA and inhibits protein synthesis."],["V","What type of transmission is typical?","Faecal oral;Fecal oral","Low infectious dose facilitates person-to-person spread."],["M","What daily habit reduces household spread most directly?","Handwashing after toileting~Interrupts faecal-oral transmission.","Sharing towels~May spread contamination.","Using antibiotics in every contact~Not routinely indicated.","Avoiding outdoor exercise~Does not address transmission."]]},{"name":"Ulcerative Colitis","scenario":"A young adult has six weeks of bloody diarrhoea and urgency. Colonoscopy shows continuous inflammation extending proximally from the rectum.","lines":[["M","Which tissue layer is primarily affected in uncomplicated disease?","Mucosa~UC mainly affects the mucosa, unlike transmural Crohn disease.","Muscularis propria only~Not the typical initial distribution.","Serosa only~UC starts in mucosa.","Entire wall with skip lesions~More typical of Crohn disease."],["M","Which class is commonly used for mild-to-moderate left-sided disease?","Aminosalicylate~Mesalazine provides local anti-inflammatory effects.","Systemic antibiotic~Not routine treatment for uncomplicated UC.","Long-term glucocorticoid maintenance~Steroids induce remission but are unsuitable for chronic maintenance.","Antimotility drug alone~Does not treat mucosal inflammation."],["D","Abdominal distension, fever, tachycardia and marked colonic dilation develop. What is the concern?","Toxic megacolon~Severe colitis with systemic toxicity and dilation requires urgent escalation.","Functional bowel disorder~Does not cause systemic toxicity and dilation.","Uncomplicated proctitis~Does not explain the severity.","Simple constipation~Inadequate explanation for acute toxicity."],["V","What inflammatory cells form crypt abscesses?","Neutrophils;Neutrophil","Accumulate within gland lumens."],["V","Which hepatobiliary disease is associated with UC?","Primary sclerosing cholangitis;PSC","A recognized extraintestinal association."],["M","Which medication should be avoided in severe acute colitis with dilation?","Loperamide~Suppressing motility may worsen dilation.","IV fluids~Support hydration.","Indicated corticosteroids~Used under supervision after assessing infection.","Electrolyte replacement~Corrects losses."],["M","What principle supports explaining long-term surveillance risks and benefits?","Shared decision-making~Discuss evidence, risks and patient preferences.","Paternalism~Excludes patient input.","Confidentiality alone~Does not replace informed discussion.","Coercion~Undermines voluntary decisions."]]},{"name":"Upper GI Bleed","scenario":"A patient with cirrhosis vomits a large volume of fresh blood. BP 82/50, pulse 132, cold peripheries.","lines":[["M","Which mechanism causes oesophageal varices?","Portal-systemic collateral dilation~Portal hypertension diverts blood into low-pressure systemic veins.","Increased gastric acid alone~Causes acid injury but not variceal formation.","Reduced hepatic artery pressure~Not the main driver.","Oesophageal smooth muscle hypertrophy~Does not create varices."],["D","Initial Hb is 12 g/dL despite shock. What is the correct interpretation?","Acute haemorrhage remains possible~Hb may initially be normal before plasma volume equilibrates.","Major blood loss excluded~Initial Hb is unreliable in acute haemorrhage.","No resuscitation needed~Clinical shock overrides the initial Hb.","Iron deficiency confirmed~Normal Hb does not establish iron status."],["M","Which supervised drug class reduces portal inflow during suspected acute variceal bleeding?","Vasoactive splanchnic agent~Terlipressin or octreotide is used per protocol alongside resuscitation and endoscopy.","Proton pump inhibitor alone~Does not directly reduce variceal portal flow.","Beta blocker as sole acute treatment~Not initial treatment during haemodynamic instability.","Oral iron~Does not control active bleeding."],["M","Which additional drug measure is indicated in acute variceal bleeding with cirrhosis?","Antibiotic prophylaxis~Reduces infection and related complications per protocol.","Routine anticoagulation~May worsen active bleeding.","High-dose NSAID~Can worsen bleeding and renal injury.","Oral antidiarrhoeal~No role in bleeding control."],["V","What term describes black tarry stool from digested blood?","Melaena;Melena","Usually suggests upper GI bleeding, though other sites are possible."],["V","Which laboratory nitrogenous waste often rises disproportionately after upper GI bleeding?","Urea;Blood urea nitrogen;BUN","Digested blood and hypovolaemia contribute."],["M","What is the first priority before endoscopy in an unstable patient?","Resuscitate and escalate~ABCDE, access, blood products as indicated and senior help precede definitive procedures.","Perform elective endoscopy first~Unsafe before stabilization.","Wait for repeat haemoglobin~Delays treatment of shock.","Give an oral antacid and observe~Inadequate for major haemorrhage."]]},{"name":"Anterior cruciate ligament Injury","scenario":"A football player pivots suddenly without contact, hears a pop and develops a tense knee effusion within two hours.","lines":[["M","Which movement is normally restrained by the injured ligament?","Anterior tibial translation~ACL resists anterior translation and contributes rotational stability.","Posterior tibial translation~Primarily restrained by PCL.","Valgus opening alone~Primarily restrained by MCL.","Varus opening alone~Primarily restrained by LCL."],["D","Lachman testing shows increased anterior translation with a soft endpoint. Which structure is injured?","Anterior cruciate ligament~This is the characteristic instability pattern.","Posterior cruciate ligament~Posterior drawer tests posterior translation.","Medial meniscus~McMurray or joint-line findings suggest this.","Patellar tendon~Rupture impairs active knee extension."],["M","What explains rapid effusion after this injury?","Haemarthrosis~Intra-articular ligament disruption can bleed into the joint.","Gradual synovial fibrosis~Develops later rather than within hours.","Subcutaneous oedema only~Would not account for intra-articular effusion.","Cartilage calcification~Not an acute bleeding mechanism."],["V","Which bedside test is most useful for anterior tibial translation at 20–30° flexion?","Lachman test;Lachman","Assesses ACL integrity."],["V","Which imaging modality best demonstrates ligament injury if indicated?","MRI;Magnetic resonance imaging","Visualises soft tissue structures."],["M","Which action is appropriate before return to sport?","Rehabilitation and stability assessment~Graded rehabilitation and supervised clearance reduce reinjury risk.","Return as soon as pain improves~Pain relief does not prove stability.","Long-term complete immobilisation~Can cause stiffness and weakness.","Ignore repeated giving way~May risk further injury."]]},{"name":"Bone Tumour (Osteosarcoma)","scenario":"A 16-year-old has increasing pain and swelling above the knee, worse at night. Radiograph shows an aggressive metaphyseal lesion with periosteal elevation.","lines":[["M","Which histological feature establishes osteosarcoma?","Malignant osteoid production~Tumour cells directly form osteoid.","Mature benign cartilage only~Not diagnostic of osteosarcoma.","Monoclonal plasma cells~Suggest myeloma.","Small round cells without osteoid~Suggest other tumours such as Ewing sarcoma."],["D","A chest CT shows multiple pulmonary nodules. What route of spread is likely?","Haematogenous spread~Osteosarcoma commonly spreads through blood to lungs.","Direct extension from femur to lung~Anatomically implausible.","CSF dissemination~Not the usual route.","Transcoelomic spread~Typical of some peritoneal malignancies."],["M","Which action before biopsy is safest?","Refer to specialist tumour team~Biopsy tract planning is essential for later definitive resection.","Excise lesion in clinic~Unplanned excision may contaminate tissue planes.","Begin physiotherapy alone~Delays malignancy evaluation.","Repeated aspiration without imaging~Not appropriate tumour assessment."],["V","What periosteal radiographic sign reflects lifted periosteum at the tumour edge?","Codman triangle;Codman's triangle","Aggressive periosteal reaction, not unique to osteosarcoma."],["V","Which tumour suppressor is associated with hereditary retinoblastoma and osteosarcoma risk?","RB1;RB","RB pathway regulates G1/S progression."],["M","Which ethical principle supports honest communication of uncertainty before histology?","Veracity~Truthful discussion distinguishes suspicion from confirmed diagnosis.","Justice~Fair access matters but is not the specific principle of truth.","Confidentiality~Protects private information.","Fidelity alone~Not the primary duty of accurate disclosure."]]},{"name":"Fractures (long bone, closed)","scenario":"A patient sustains a closed humeral shaft fracture. After splinting, he cannot extend the wrist or fingers, but hand perfusion is preserved.","lines":[["M","Which nerve is at greatest risk?","Radial nerve~Runs in the radial groove of the humerus and supplies wrist/finger extensors.","Median nerve~Supplies many forearm flexors and thenar muscles.","Ulnar nerve~Supplies many intrinsic hand muscles.","Axillary nerve~At risk at surgical neck and supplies deltoid."],["D","Sensation is reduced over the dorsal first web space. Which finding supports the same nerve lesion?","Radial sensory deficit~The first dorsal web space is a useful radial sensory territory.","Ulnar palmar deficit~More typical of little finger and medial hand.","Median thenar motor deficit~Not the radial distribution.","Musculocutaneous deficit~Affects lateral forearm sensation and elbow flexion."],["M","What must be documented before and after reduction or splinting?","Distal neurovascular status~Identifies evolving nerve or vascular compromise.","Body mass index~Not an immediate limb safety measure.","Previous vaccination history only~Not the key post-splint assessment.","Only radiographic alignment~Clinical neurovascular assessment is essential."],["M","A second patient with a tibial fracture has escalating pain on passive toe stretch. What is the safest action?","Urgent surgical escalation~Suspect compartment syndrome even with palpable pulses.","Wait for absent pulses~Pulselessness is a late sign.","Tighten the cast~May worsen tissue pressure.","Review at routine clinic~Unsafe delay."],["V","What type of necrosis occurs in severely ischaemic skeletal muscle without infection?","Coagulative necrosis","Ischaemic injury in muscle generally causes coagulative necrosis."],["V","Which cell lays down new bone during repair?","Osteoblast;Osteoblasts","Produces osteoid and supports mineralization."],["M","Which communication action prevents missed injury progression during handover?","Report neurovascular changes explicitly~Communicate timing, examination and escalation needs.","Mention only fracture location~May omit urgent complications.","Wait for written report alone~Can delay action.","Assume the next team knows~Creates handover risk."]]},{"name":"Gout","scenario":"A man with CKD develops abrupt severe first MTP pain and erythema after a celebration. Joint fluid contains needle-shaped crystals.","lines":[["M","Which innate immune pathway drives the acute flare?","NLRP3 inflammasome~Urate crystals promote IL-1β activation and neutrophilic inflammation.","IgE mast cell cross-linking~Type I allergy mechanism.","Complement membrane attack alone~Not the characteristic crystal-triggered pathway.","Antibody against acetylcholine receptors~Relates to myasthenia gravis."],["D","Crystals are strongly negatively birefringent. Which diagnosis is supported?","Monosodium urate crystal arthritis~Needle-shaped negative birefringence is characteristic.","Calcium pyrophosphate arthritis~Typically rhomboid, weak positive birefringence.","Hydroxyapatite arthritis~Crystals generally not seen by routine polarized microscopy.","Septic arthritis excluded~Crystals do not rule out concurrent infection."],["M","Which drug reduces neutrophil microtubule-dependent activity during a flare?","Colchicine~Inhibits tubulin polymerization; dosing and interactions matter, especially in CKD.","Allopurinol~Lowers urate production, not acute anti-inflammatory action.","Probenecid~Increases urate excretion.","Paracetamol~Analgesia without the specific neutrophil mechanism."],["V","Which enzyme is inhibited by allopurinol?","Xanthine oxidase","Converts hypoxanthine and xanthine toward uric acid."],["V","Which cytokine is generated through inflammasome-mediated cleavage?","IL-1 beta;IL-1β;Interleukin 1 beta","Caspase-1 activates pro-IL-1β."],["M","Which daily habit helps reduce urate-related risk?","Limit beer and sugary drinks~Alcohol and fructose can increase urate; hydration and weight management also help.","Increase binge drinking~May trigger attacks.","Rapid crash dieting~Can precipitate flares.","Stop prescribed urate-lowering therapy during all flares~Established treatment is usually continued under supervision."]]},{"name":"Osteoarthritis","scenario":"A 63-year-old has knee pain worse on stairs and late in the day, morning stiffness for 10 minutes and crepitus. No warmth or systemic symptoms.","lines":[["M","Which process underlies joint damage?","Articular cartilage degeneration~Mechanical and biochemical cartilage changes accompany subchondral bone remodelling.","Immune pannus invasion~Typical of rheumatoid arthritis.","Urate crystal deposition~Suggests gout.","Purulent synovial infection~Suggests septic arthritis."],["D","Radiograph shows asymmetric joint space loss, marginal osteophytes and subchondral sclerosis. What is supported?","Osteoarthritis~These are typical degenerative radiographic changes.","Rheumatoid arthritis~Often uniform narrowing and marginal erosions.","Osteomyelitis~Would suggest destructive/infectious bone changes.","Acute ACL tear~Radiographs do not show this characteristic chronic pattern."],["M","Which topical class is a reasonable initial pharmacological option for knee OA?","NSAID~Topical diclofenac can reduce local pain with less systemic exposure.","Topical antibiotic~Not indicated for degenerative joint pain.","Topical antifungal~No role in cartilage disease.","Topical steroid~Not standard OA analgesia."],["V","What term describes marginal bony outgrowths?","Osteophytes;Osteophyte","Form at joint margins in OA."],["V","Which collagen type predominates in normal articular cartilage?","Type II collagen;Collagen II","Provides tensile structure to hyaline cartilage."],["M","Which non-drug intervention improves function?","Graded strengthening exercise~Supports joint function; weight management if appropriate.","Prolonged bed rest~Promotes weakness and stiffness.","Avoid all loading~May worsen disability.","Routine opioid escalation~Not preferred long-term care."]]},{"name":"Osteoporosis","scenario":"A postmenopausal woman fractures her distal radius after falling from standing height. She has no evidence of osteomalacia.","lines":[["M","What mechanism contributes to postmenopausal bone loss?","Increased osteoclast activity~Oestrogen loss increases RANKL-mediated resorption.","Increased mineral deposition alone~Would not explain low bone mass.","Reduced osteoclast formation~Would decrease resorption.","Complete absence of osteoid~Not the typical mechanism."],["D","DXA femoral neck T-score is −2.8. What is supported in this patient?","Osteoporosis~T-score ≤−2.5 meets densitometric definition in postmenopausal women.","Normal bone density~T-score is significantly reduced.","Osteopenia only~Typically between −1 and −2.5.","Osteomalacia proven~DXA cannot establish defective mineralization."],["M","Which class inhibits osteoclast-mediated resorption and is commonly used for high fracture risk?","Bisphosphonate~Reduces osteoclast activity and fracture risk in appropriate patients.","Glucocorticoid~Chronic exposure increases bone loss.","Loop diuretic~Can increase urinary calcium.","Proton pump inhibitor~Not osteoporosis treatment."],["V","Which ligand stimulates osteoclast differentiation by binding RANK?","RANKL;RANK ligand","Expressed by osteoblast-lineage cells and stromal cells."],["V","Which cell senses mechanical loading within bone matrix?","Osteocyte;Osteocytes","Coordinates bone remodelling signals."],["M","Which household intervention lowers fracture risk through fall prevention?","Remove loose rugs~Reduces trip hazards alongside lighting and balance training.","Avoid all exercise~May worsen balance and muscle weakness.","Use sedatives nightly~May increase falls.","Restrict calcium unnecessarily~Does not prevent falls."]]},{"name":"Rheumatoid Arthritis","scenario":"A woman has symmetrical MCP and PIP swelling, fatigue and morning stiffness lasting 90 minutes. Anti-CCP antibodies are positive.","lines":[["M","Which process causes erosive joint damage?","Inflammatory synovial pannus~Proliferative synovium and cytokines activate osteoclasts and damage cartilage.","Primary cartilage wear only~More typical of OA.","Urate precipitation~Mechanism of gout.","Bacterial suppuration alone~Suggests septic arthritis."],["D","Hand radiographs show marginal erosions and periarticular osteopenia. What is most consistent?","Rheumatoid arthritis~Inflammatory synovitis causes marginal erosions and localized bone loss.","Osteoarthritis~Osteophytes and asymmetric narrowing predominate.","Osteoporosis alone~Does not explain focal erosive synovitis.","Carpal tunnel syndrome alone~Does not explain erosions."],["M","Which drug is a conventional disease-modifying antirheumatic agent?","Methotrexate~A common anchor DMARD; requires weekly dosing and safety monitoring.","Ibuprofen~Symptomatic NSAID, not disease modifying.","Paracetamol~Analgesic, not DMARD.","Colchicine~Used in crystal arthritis, not standard RA DMARD."],["M","Which baseline assessment is important before methotrexate?","Blood count and liver/renal tests~Detect cytopenias, organ dysfunction and guide safe monitoring.","Serum urate alone~Not sufficient for methotrexate safety.","Peak expiratory flow alone~Not adequate drug monitoring.","Random cholesterol only~Does not assess major toxicity risks."],["V","Which antibody targets citrullinated peptides?","Anti-CCP;ACPA","Relatively specific for RA."],["V","Which cytokine is targeted by infliximab?","TNF alpha;TNF-α;Tumour necrosis factor alpha","TNF is important in inflammatory synovitis."],["M","Which treatment-related prevention is especially relevant before potent immunosuppression in South Africa?","Screen for tuberculosis~Assess latent/active TB and other infection risks according to protocol.","Avoid all vaccines permanently~Vaccination planning is individualized.","Stop hand hygiene~Increases infection risk.","Ignore prior TB exposure~Misses reactivation risk."]]},{"name":"Septic Arthritis","scenario":"A diabetic adult has fever, severe knee pain and inability to bear weight. The joint is hot and passive movement is extremely painful.","lines":[["M","Which pathological process is most concerning?","Acute suppurative synovitis~Bacterial infection recruits neutrophils and may rapidly destroy cartilage.","Chronic degenerative cartilage loss~Usually gradual mechanical pain.","Autoimmune pannus alone~Typically chronic inflammatory polyarthritis.","Isolated ligament sprain~Does not explain systemic fever and hot joint."],["D","Aspirate contains 90,000 leukocytes/µL, predominantly neutrophils; Gram stain is negative. What is safest?","Infection remains likely~Negative Gram stain lacks sensitivity; culture and urgent management are needed.","Septic arthritis excluded~A negative stain does not rule it out.","Gout confirmed~Crystal identification is required and infection may coexist.","OA confirmed~Marked inflammatory fluid is not typical OA."],["M","Which supervised management is appropriate?","Urgent drainage and empiric antibiotics~Obtain cultures when feasible without delaying treatment in sepsis.","Oral NSAID alone~Does not address bacterial infection.","Intra-articular steroid before excluding infection~Can worsen infection.","Routine outpatient review next month~Risks irreversible joint injury."],["V","Which organism commonly causes native joint septic arthritis?","Staphylococcus aureus;S aureus","Common cause across adult age groups."],["V","Which dominant cell type produces pus?","Neutrophil;Neutrophils","Acute suppurative exudate contains neutrophils and debris."],["M","Which safety principle is illustrated by avoiding steroid injection before excluding infection?","Non-maleficence~Avoid preventable harm from worsening infection.","Justice~Fair allocation is not the direct issue.","Autonomy~Concerns informed choices.","Confidentiality~Protects personal information."]]},{"name":"Spinal Cord Injury","scenario":"After a vehicle collision, a patient has bilateral leg weakness and sensory loss below the chest. BP 80/45, pulse 48; bleeding must still be excluded.","lines":[["M","What mechanism explains hypotension with relative bradycardia in high cord injury?","Loss of sympathetic outflow~Vasodilation and unopposed vagal activity cause neurogenic shock.","Increased sympathetic tone~Would usually cause vasoconstriction and tachycardia.","Isolated parasympathetic loss~Would favour tachycardia.","Increased circulating volume~Does not explain shock."],["D","Reflexes are initially absent below the lesion, then return over time. What is this phenomenon?","Spinal shock~Transient suppression of reflexes below cord injury.","Neurogenic shock alone~Refers to haemodynamic autonomic failure.","Myasthenic crisis~Neuromuscular junction weakness, not this sensory-level pattern.","Peripheral arterial occlusion~Does not explain bilateral sensory level."],["M","Which action is safest during initial assessment?","ABCDE with spinal motion restriction~Protect cord while addressing immediate threats and escalating trauma care.","Delay airway assessment until imaging~Airway takes priority.","Ask patient to walk unaided~Risks worsening injury.","Perform forced neck flexion~May aggravate instability."],["V","Which tract conveys vibration and conscious proprioception?","Dorsal columns;Posterior columns","Ascends ipsilaterally in spinal cord."],["V","Which tract conveys pain and temperature?","Spinothalamic tract;Anterolateral tract","Fibres cross near the entry level."],["M","Which bedside examination helps document completeness of injury?","Sacral sensory and motor examination~Sacral sparing is important for classification; perform appropriately with consent.","Visual acuity alone~Does not assess spinal completeness.","Abdominal percussion alone~Not a sacral neurological assessment.","Peak flow alone~May assess respiratory weakness but not completeness."],["M","Which team action best reduces transfer-related harm?","Coordinated transfer with clear leader~Maintains motion restriction and communication.","Unplanned single-person lift~May move unstable spine.","Ask family to reposition patient~Unsafe without trained team.","Ignore new sensory change~Misses deterioration."]]},{"name":"Vitamin D Deficiency","scenario":"A woman with limited sun exposure has diffuse bone pain and proximal muscle weakness. 25-OH vitamin D is low.","lines":[["M","Which pathological defect explains osteomalacia?","Impaired osteoid mineralization~Insufficient calcium/phosphate availability prevents normal mineral deposition.","Reduced total bone mass with normal mineralization~Defines osteoporosis rather than osteomalacia.","Malignant osteoid production~Defines osteosarcoma.","Excess urate deposition~Causes gout."],["D","Calcium low-normal, phosphate low, ALP high and PTH high. What explains this?","Secondary hyperparathyroidism~Vitamin D deficiency reduces calcium absorption, stimulating PTH and phosphate wasting.","Primary hypoparathyroidism~PTH would be low with high phosphate.","Isolated osteoporosis~Often normal mineral biochemistry.","Primary hyperparathyroidism~Usually high calcium."],["M","Which supplement restores nutritional vitamin D stores if renal activation is intact?","Cholecalciferol~Native vitamin D is hydroxylated in liver and kidney.","Calcitonin~Inhibits osteoclasts but does not replenish vitamin D stores.","Bisphosphonate~Antiresorptive, not replacement for deficiency.","Calcimimetic~Suppresses PTH but does not restore stores."],["V","Which skin precursor is converted by UVB to previtamin D3?","7-dehydrocholesterol;7 dehydrocholesterol","UVB photoconversion initiates vitamin D synthesis."],["V","Which blood metabolite best reflects vitamin D stores?","25-hydroxyvitamin D;25 OH vitamin D;Calcidiol","Major circulating storage-status marker."],["M","Which advice is appropriate to reduce recurrence?","Adequate vitamin D intake and safe sun exposure~Individualize dietary/supplement advice and avoid excessive UV exposure.","Use tanning beds routinely~Raises skin cancer risk.","Avoid dietary calcium entirely~May worsen mineralization.","Take unmonitored megadoses~Can cause toxicity."]]},{"name":"Aplastic Anaemia","scenario":"A young adult develops fatigue, recurrent infections and petechiae. Hb 7.8, platelets 18×10⁹/L, neutrophils 0.3×10⁹/L; reticulocytes low.","lines":[["M","Which underlying process explains the three low cell lines?","Haematopoietic stem cell failure~Marrow hypoplasia reduces erythrocytes, leukocytes and platelets.","Isolated platelet destruction~Does not explain low Hb and neutrophils.","Peripheral red cell haemolysis alone~Usually increases reticulocytes and spares other lines.","Isolated folate deficiency~May cause cytopenias but marrow morphology differs."],["D","Marrow biopsy shows severe hypocellularity with fatty replacement. What is supported?","Aplastic anaemia~Marked marrow hypoplasia explains pancytopenia.","Acute leukaemia with blast expansion~Would show malignant blast infiltration.","Iron deficiency alone~Does not cause this hypocellular pattern.","Hypersplenism alone~Marrow may remain active."],["M","Temperature rises to 38.5°C. What is the safest next step?","Urgent febrile neutropenia treatment~Prompt cultures if feasible and empiric IV antibiotics per protocol.","Wait for next full blood count~Delays treatment of possible severe infection.","Oral iron only~Does not address infection risk.","Routine outpatient appointment~Unsafe with severe neutropenia and fever."],["V","What term describes reduced red cells, white cells and platelets?","Pancytopenia","All three major cell lines are reduced."],["V","Which immune cells can mediate acquired immune marrow failure?","T lymphocytes;Cytotoxic T cells;T cells","Immune-mediated stem cell injury is common in acquired aplasia."],["M","What is an appropriate daily safety habit during severe neutropenia?","Promptly report fever~Early recognition and urgent review are essential.","Self-start leftover antibiotics only~May delay appropriate care.","Ignore minor infection symptoms~Risk rapid progression.","Take aspirin for fever without advice~Can worsen bleeding with thrombocytopenia."]]},{"name":"Breast Cancer","scenario":"A 49-year-old has a hard irregular breast lump with skin tethering and ipsilateral axillary nodes.","lines":[["M","Which mechanism causes peau d’orange?","Dermal lymphatic obstruction~Lymphatic blockage causes oedema around tethered skin structures.","Increased sebaceous secretion~Does not produce lymphatic oedema.","Reduced arterial inflow alone~Does not explain characteristic skin texture.","Smooth muscle hypertrophy~Not the primary mechanism."],["D","Biopsy shows invasive carcinoma expressing ER and PR, HER2 negative. Which treatment class may target the receptor?","Endocrine therapy~ER-positive cancers can respond to hormone-directed therapy.","Anti-HER2 monoclonal antibody alone~Not indicated on HER2-negative status alone.","Antibiotic~Does not target hormone-dependent tumour cells.","Anticoagulant~Not receptor-directed cancer therapy."],["M","What is the appropriate diagnostic approach for a suspicious lump?","Triple assessment~Clinical exam, age-appropriate imaging and tissue sampling.","Tumour marker alone~Not sufficient to diagnose a lump.","Empirical hormone therapy first~Does not establish diagnosis.","Reassurance based on painlessness~Painless masses may be malignant."],["V","Which receptor is targeted by trastuzumab?","HER2;ERBB2","Targets HER2-overexpressing/amplified tumours."],["V","Which DNA double-strand break repair pathway is impaired by BRCA1/2 loss?","Homologous recombination;Homologous recombination repair","BRCA genes support repair of DNA double-strand breaks."],["M","A patient wants a relative present during results discussion. What should be done?","Ask and respect permission~Patient preferences govern disclosure to chosen supporters.","Automatically disclose to relatives~May breach confidentiality.","Exclude all family regardless of preference~Undermines chosen support.","Explain only to the relative~Excludes the patient."]]},{"name":"Cervical Cancer","scenario":"A woman with no recent screening has postcoital bleeding and a friable cervical lesion. She is living with HIV.","lines":[["M","Which mechanism links high-risk HPV to malignant progression?","E6 and E7 oncoprotein activity~E6 promotes p53 degradation; E7 disrupts RB cell-cycle control.","Viral integration into erythrocytes~Not the relevant epithelial mechanism.","IgE-mediated hypersensitivity~Does not drive HPV oncogenesis.","Direct bacterial toxin injury~Not the central cause."],["D","Biopsy shows invasive squamous cells extending beyond the basement membrane. What distinguishes invasion?","Basement membrane breach~Invasion separates carcinoma from intraepithelial neoplasia.","Nuclear atypia alone~May occur in preinvasive lesions.","Surface keratin alone~Not sufficient to define invasion.","HPV positivity alone~Does not establish cancer."],["M","What is the appropriate next action for a visibly suspicious lesion?","Diagnostic biopsy referral~Symptoms and a visible lesion require diagnostic evaluation, not screening alone.","Routine repeat screening in five years~Unsafe delay.","Empirical antifungal only~Does not evaluate malignancy.","HPV vaccination as treatment~Prevents selected infections but does not treat existing invasive cancer."],["V","Which anatomical zone is most vulnerable to HPV-related neoplasia?","Transformation zone;Squamocolumnar junction","Metaplastic epithelium is susceptible to oncogenic HPV."],["V","Which tumour suppressor protein is degraded by HPV E6?","p53;TP53","E6 promotes ubiquitin-mediated p53 degradation."],["M","Which population intervention reduces future HPV-associated cancer risk?","HPV vaccination~Prevents infection by targeted high-risk types; screening remains important.","Antibiotics at sexual debut~Do not prevent HPV.","Screening only after symptoms~Misses prevention opportunities.","Avoid discussing sexual health~Reduces access to preventive care."]]},{"name":"Disseminated Intravascular Coagulation","scenario":"A septic patient develops bleeding around IV sites, mottled digits and worsening organ dysfunction.","lines":[["M","Which mechanism causes simultaneous thrombosis and bleeding?","Systemic coagulation activation~Microvascular fibrin thrombi consume platelets and factors, causing bleeding.","Isolated factor VIII deficiency~Does not cause generalized microthrombosis.","Isolated platelet antibody destruction~Does not consume multiple coagulation factors.","Excess vitamin K intake~Does not explain consumption."],["D","Platelets low, PT prolonged, fibrinogen low and D-dimer high. Which diagnosis fits?","DIC~A consumption coagulopathy with fibrin formation and breakdown.","Haemophilia A~Usually isolated prolonged aPTT.","Von Willebrand disease~Usually mucosal bleeding without this consumption pattern.","Iron deficiency~Does not prolong coagulation times."],["M","Which action most directly addresses the disease process?","Treat the precipitating sepsis~Control infection and source to reduce ongoing coagulation activation.","Give aspirin routinely~May worsen bleeding.","Replace vitamin K as sole therapy~Does not address consumption.","Delay antibiotics until coagulation normalizes~Unsafe."],["V","Which enzyme converts fibrinogen to fibrin?","Thrombin;Factor IIa","Central enzyme in fibrin formation."],["V","Which cell type becomes fragmented in microvascular thrombi?","Erythrocytes;Red blood cells;RBCs","Shearing may produce schistocytes."],["M","Which finding should trigger urgent escalation?","New intracranial bleeding signs~Potential life-threatening haemorrhage requires emergency assessment.","Stable old bruising only~Less urgent than new neurological signs.","Normal oxygenation alone~Does not eliminate bleeding risk.","Improving urine output~Generally reassuring."]]},{"name":"Haemophilia","scenario":"A boy has recurrent painful swollen knees after minor injuries. Maternal uncle has a similar history. Platelet count normal.","lines":[["M","Which mechanism accounts for deep tissue bleeding in haemophilia A?","Impaired intrinsic tenase function~Factor VIII deficiency reduces factor X activation and thrombin generation.","Impaired platelet adhesion alone~More typical of VWD.","Reduced factor VII only~Affects extrinsic pathway and PT.","Excess fibrinolysis alone~Not the inherited factor VIII defect."],["D","aPTT prolonged, PT normal, mixing study corrects. What is supported?","Clotting factor deficiency~Normal plasma supplies the missing factor; an inhibitor may fail to correct.","Factor inhibitor proven~Inhibitors often prevent correction, especially after incubation.","Platelet count deficiency~Platelet count does not cause isolated aPTT prolongation.","DIC confirmed~Usually affects multiple tests and platelets."],["M","Which drug replacement is specific for haemophilia A with severe bleeding?","Factor VIII concentrate~Replaces deficient factor VIII; specialist protocol guides treatment.","Factor IX concentrate~Specific for haemophilia B.","Vitamin K alone~Does not correct factor VIII deficiency.","Platelet concentrate alone~Does not replace missing factor VIII."],["V","What inheritance pattern is typical?","X-linked recessive;X linked recessive","Most affected patients are male; carriers may also bleed."],["V","Which factor is deficient in haemophilia B?","Factor IX;Factor 9","Christmas disease."],["M","Which everyday medicine should be avoided unless specifically advised?","Aspirin~Inhibits platelet function and increases bleeding risk.","Paracetamol at appropriate dose~Often preferred for simple pain.","Prescribed factor replacement~Essential when indicated.","Appropriate non-drug rehabilitation~Supports joint function."]]},{"name":"Iron Deficiency Anaemia","scenario":"A 46-year-old woman reports fatigue, pica and heavy menstrual bleeding. Hb 8.8 g/dL, MCV 68 fL, ferritin 6 µg/L.","lines":[["M","What causes microcytosis?","Reduced haemoglobin synthesis~Iron deficiency impairs haem production, producing smaller hypochromic cells.","Impaired DNA replication~Typically causes macrocytosis.","Increased membrane fragility alone~Often produces haemolysis rather than this iron pattern.","Excess erythropoietin alone~Not the mechanism of microcytosis."],["D","Serum iron low, ferritin low, TIBC high. What is most consistent?","Iron deficiency anaemia~Low stores and increased transferrin capacity are typical.","Anaemia of chronic inflammation~Ferritin often normal/high and TIBC low or normal.","Beta-thalassaemia trait~Iron stores usually normal absent coexisting deficiency.","B12 deficiency~Typically macrocytic."],["M","Which oral drug class replaces the deficient substrate?","Ferrous salts~Provide elemental iron for haemoglobin synthesis.","Folic acid alone~Does not replace iron.","Cobalamin alone~Treats B12 deficiency.","Erythropoietin alone~Does not correct depleted iron stores."],["M","Which substance reduces non-haem iron absorption when taken with meals?","Tea polyphenols~Can bind iron and reduce absorption.","Ascorbic acid~Enhances non-haem iron absorption.","Gastric acid~Generally improves solubility of non-haem iron.","Ferrous iron~More readily absorbed than ferric iron."],["V","Which hormone reduces iron export through ferroportin?","Hepcidin","Binds ferroportin, leading to internalization and degradation."],["V","What is the term for craving non-food substances?","Pica","An association with iron deficiency."],["M","Which follow-up step is essential rather than replacing iron indefinitely?","Investigate the source of blood loss~Treating deficiency without addressing the cause risks recurrence and missed disease.","Stop evaluation once Hb rises~Response does not exclude important underlying disease.","Avoid menstrual history~May miss significant bleeding.","Use repeated transfusions for all stable cases~Not standard iron replacement."]]},{"name":"Kaposi Sarcoma","scenario":"A man with advanced untreated HIV develops purple plaques on his legs and palate. One lesion is nodular and does not blanch.","lines":[["M","Which pathological process underlies the lesions?","HHV-8-associated vascular proliferation~Viral oncogenic signalling promotes spindle-cell vascular tumour growth.","Candida invasion of mucosa~Produces fungal plaques rather than vascular spindle lesions.","HPV-related squamous dysplasia~Different tumour pathway.","EBV-associated B-cell proliferation~Associated with some lymphomas rather than KS."],["D","Biopsy shows spindle cells, slit-like vascular spaces and extravasated erythrocytes. What fits?","Kaposi sarcoma~Characteristic vascular tumour histology.","Melanoma~Typically atypical melanocytic proliferation.","Basal cell carcinoma~Basaloid nests and peripheral palisading.","Lymphoma~Malignant lymphoid infiltrate rather than slit-like spaces."],["M","Which underlying treatment is foundational for HIV-associated KS?","Effective ART~Immune restoration and HIV suppression can improve KS; advanced disease needs oncology input.","Systemic steroid alone~Can worsen KS.","Antifungal alone~Does not treat viral oncogenic tumour.","Antibiotic alone~No role in tumour control unless infection coexists."],["V","Which herpesvirus is associated with KS?","HHV-8;HHV8;KSHV","Kaposi sarcoma-associated herpesvirus."],["V","Which cell morphology is characteristic of the tumour?","Spindle cells;Spindle cell","Elongated tumour cells form vascular spaces."],["M","Which action best addresses concern about stigma?","Provide confidential counselling~Support informed decisions and linkage to HIV and cancer services.","Disclose status to neighbours~Violates confidentiality.","Refuse care until disclosure~Undermines access and autonomy.","Avoid discussing ART~Misses disease-modifying therapy."]]},{"name":"Thalassaemia","scenario":"A young adult has lifelong mild microcytosis with family history of similar findings. Hb 10.8, MCV 62, RBC count relatively high; ferritin normal.","lines":[["M","Which mechanism causes beta-thalassaemia?","Reduced beta globin synthesis~Unbalanced globin chains cause ineffective erythropoiesis and haemolysis.","Iron store depletion alone~Ferritin is normal and lifelong family pattern suggests inherited disease.","Defective RBC membrane spectrin~Typical of hereditary spherocytosis.","Autoimmune RBC destruction alone~Does not explain inherited marked microcytosis."],["D","Haemoglobin electrophoresis shows HbA2 5.5%. What is supported?","Beta-thalassaemia trait~Raised HbA2 is characteristic in many carriers.","Iron deficiency alone~Usually not associated with raised HbA2.","Alpha-thalassaemia trait confirmed~Electrophoresis may be normal in alpha trait.","Sickle cell disease~Would show substantial HbS."],["M","Which treatment addresses transfusional iron overload in severe disease?","Iron chelation~Removes excess iron to reduce organ toxicity.","Routine oral iron~Can worsen overload without proven deficiency.","Vitamin K~Does not remove excess iron.","Erythropoietin alone~Does not chelate iron."],["V","Which blood film cell has a central haemoglobinized area surrounded by pallor and rim?","Target cell;Target cells;Codocyte","Common in thalassaemia and other conditions."],["V","What is the predominant adult haemoglobin tetramer?","Alpha2 beta2;α2β2;HbA","Contains two alpha and two beta chains."],["M","Two carriers ask about pregnancy risks. What approach is appropriate?","Non-directive genetic counselling~Discuss inheritance and testing options without coercion.","Tell them they must not conceive~Violates autonomy.","Assume every child affected~Autosomal recessive risk depends on parental genotypes.","Withhold information~Prevents informed decision-making."]]},{"name":"Von Willebrand Disease","scenario":"A teenager has recurrent epistaxis, prolonged bleeding after dental extraction and heavy menses. Platelet count is normal.","lines":[["M","Which primary haemostatic defect is most relevant?","Impaired platelet adhesion~VWF bridges exposed collagen and platelet GPIb.","Reduced platelet production~Platelet count is normal.","Isolated fibrinogen cleavage failure~Not the primary VWF function.","Excess red cell destruction~Does not explain mucosal bleeding."],["D","VWF activity is low; aPTT is mildly prolonged. Why may aPTT rise?","Reduced factor VIII stability~VWF carries and protects factor VIII from degradation.","Reduced factor VII stability~Factor VII influences PT and is not stabilized by VWF.","Reduced platelet count~Does not explain aPTT prolongation.","Increased fibrinogen synthesis~Not the mechanism."],["M","Which drug can release stored VWF in responsive mild type 1 disease?","Desmopressin~Stimulates endothelial release of VWF and VIII; subtype and response matter.","Aspirin~Inhibits platelet aggregation.","Warfarin~Reduces vitamin K-dependent factors.","Vitamin K~Does not correct VWF deficiency."],["V","Which platelet receptor binds VWF?","GPIb;Glycoprotein Ib;GP Ib","Mediates initial adhesion under shear."],["V","Which clotting factor is stabilized by VWF?","Factor VIII;Factor 8","VWF protects circulating factor VIII."],["M","Which drug class may reduce mucosal bleeding by inhibiting fibrinolysis?","Antifibrinolytic~Tranexamic acid reduces plasminogen activation/binding and clot breakdown.","Antiplatelet~Can aggravate mucosal bleeding.","Thrombolytic~Promotes clot dissolution.","Anticoagulant~Reduces coagulation."],["M","Which practical safety action should precede a dental extraction?","Inform the dental team of bleeding disorder~Arrange a haemostatic plan with the treating team.","Take aspirin beforehand~May worsen bleeding.","Hide bleeding history~Prevents safe planning.","Skip all dental hygiene~Increases oral disease risk."]]}]);